/* Copy the read-only epoch programs into the non-secure window (called by
 * the driver before the model is started); returns a checksum of the copies.
 *
 * _ec_blob_1 needs nothing here: LL_ATON_EC_Network_Init_Face() fills it in
 * place, at publish time, from _ec_blob_1_reloc.
 *
 * _ec_blob_29 and _ec_blob_37 are different: they are alternate epoch programs
 * that the epoch controller fetches itself, they carry their content as
 * load-time initialisers, and the section they have to live in is NOLOAD.  So
 * they are copied here, into the writable twins the epoch block table names.
 * Without this the controller reads zeros and latches EC_IRQ = 0x8 in a loop
 * until the watchdog masks the interrupt line.
 *
 * The caller runs this before publishing the network and cleans the data cache
 * afterwards, so the NPU sees the copies.
 *
 * The name carries _face_ so it cannot collide with the eye model's
 * aton_model_ecblobs_to_ns(): both products are linked into the same image.
 */

uint32_t aton_model_face_ecblobs_to_ns(void)
{
  uint32_t sum = 0;
  size_t   i;

  memcpy(_ec_blob_29_ns, _ec_blob_29, sizeof(_ec_blob_29));
  memcpy(_ec_blob_37_ns, _ec_blob_37, sizeof(_ec_blob_37));

  /* A checksum over what was written, so the log says whether the copy
   * happened rather than only that the call returned.
   */

  for (i = 0; i < sizeof(_ec_blob_29) / sizeof(uint64_t); i++)
    {
      sum += (uint32_t)_ec_blob_29_ns[i];
      sum  = (sum << 1) | (sum >> 31);
    }

  for (i = 0; i < sizeof(_ec_blob_37) / sizeof(uint64_t); i++)
    {
      sum += (uint32_t)_ec_blob_37_ns[i];
      sum  = (sum << 1) | (sum >> 31);
    }

  return sum;
}
